import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { FileExtensionsEntity } from "#/modules/filesystem/schema/entities/file-extensions.entity.ts";
import * as FileExtensions from "#/modules/filesystem/schema/types/file-extensions/index.ts";

/**
 * Repository of File Extensions: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class FileExtensionsRepository
  extends EntityRepository<
    FileExtensionsEntity,
    FileExtensions.Types.FileExtensionsSortableField,
    FileExtensions.Types.FileExtensionsEditableField,
    FileExtensions.Types.FileExtensionsSelectableField,
    FileExtensions.Types.IFileExtensionsCreatable
  >
  implements
    IUpdatableRepository<FileExtensionsEntity, FileExtensions.Types.IFileExtensionsUpdatable>
{
  constructor(
    @InjectRepository(FileExtensionsEntity)
    repository: Repository<FileExtensionsEntity>,
  ) {
    super(repository, FileExtensions.Config.FILE_EXTENSIONS_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(
    id: string,
    data: FileExtensions.Types.IFileExtensionsUpdatable,
  ): Promise<FileExtensionsEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the file extensions with this code (unique). */
  async findByCode(
    code: NonNullable<FileExtensionsEntity["code"]>,
  ): Promise<FileExtensionsEntity | null> {
    return await this.findOne({ code, deletedAt: IsNull() });
  }

  /** Find the file extensions with this extension (unique). */
  async findByExtension(
    extension: NonNullable<FileExtensionsEntity["extension"]>,
  ): Promise<FileExtensionsEntity | null> {
    return await this.findOne({ extension, deletedAt: IsNull() });
  }
}
